import React, { useEffect, useRef, useState } from 'react';
import { View, Text, TouchableOpacity, Image, Modal, TextInput, Animated, FlatList, StyleSheet } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { VideoView, useVideoPlayer } from 'expo-video';
import { doc, updateDoc, arrayUnion, arrayRemove, setDoc, addDoc, collection, serverTimestamp } from 'firebase/firestore';
import { db } from '../config';
import { BRAND } from './theme';
import { ShareModal } from './ShareModal';

const EMOJIS = ['😂', '😮', '😍', '😢', '👏', '🔥'];

function StoryVideo({ uri }: { uri: string }) {
  const p = useVideoPlayer(uri, (pl) => { pl.loop = true; pl.play(); });
    return <VideoView player={p} style={styles.media} nativeControls={false} />;
    }

    export function StoryViewerModal({ stories, activeIdx, setActiveIdx, uid, me }: {
      stories: any[]; activeIdx: number | null; setActiveIdx: (i: number | null) => void; uid: string; me: any;
      }) {
        const [progress, setProgress] = useState(0);
          const [showViewers, setShowViewers] = useState(false);
            const [showComments, setShowComments] = useState(false);
              const [showEmojis, setShowEmojis] = useState(false);
                const [reply, setReply] = useState('');
                  const [cText, setCText] = useState('');
                    const [shareItem, setShareItem] = useState<any | null>(null);
                      const [flyEmoji, setFlyEmoji] = useState('');
                        const anim = useRef(new Animated.Value(0)).current;

                          const active = activeIdx !== null ? stories[activeIdx] : null;
                            const paused = showViewers || showComments || !!shareItem || showEmojis;

                              useEffect(() => {
                                  if (activeIdx === null || paused) return;
                                      setProgress(0);
                                          const t = setInterval(() => {
                                                setProgress((p) => {
                                                        if (p >= 100) {
                                                                  if (activeIdx < stories.length - 1) setActiveIdx(activeIdx + 1);
                                                                            else setActiveIdx(null);
                                                                                      return 0;
                                                                                              }
                                                                                                      return p + 2;
                                                                                                            });
                                                                                                                }, 100);
                                                                                                                    return () => clearInterval(t);
                                                                                                                      }, [activeIdx, paused, stories.length]);

                                                                                                                        const sendDM = async (txt: string, isReaction: boolean) => {
                                                                                                                            if (!active || !txt.trim() || !uid) return;
                                                                                                                                const chatId = [uid, active.uid].sort().join('_');
                                                                                                                                    await setDoc(doc(db, 'conversations', chatId), { participants: [uid, active.uid], updatedAt: serverTimestamp() }, { merge: true });
                                                                                                                                        await addDoc(collection(db, 'conversations', chatId, 'messages'), {
                                                                                                                                              senderUid: uid, text: isReaction ? `Reacted ${txt} to your story` : `Story reply: ${txt}`,
                                                                                                                                                    mediaUrl: active.mediaUrl, mediaType: active.mediaType || 'image', read: false, createdAt: serverTimestamp(),
                                                                                                                                                        });
                                                                                                                                                            await addDoc(collection(db, 'notifications'), {
                                                                                                                                                                  toUid: active.uid, fromUid: uid, fromUsername: me?.username || 'user',
                                                                                                                                                                        type: 'reply', message: isReaction ? `reacted ${txt} to your story` : `replied: ${txt}`,
                                                                                                                                                                              read: false, createdAt: serverTimestamp(),
                                                                                                                                                                                  });
                                                                                                                                                                                    };

                                                                                                                                                                                      const triggerReaction = (e: string) => {
                                                                                                                                                                                          setFlyEmoji(e); setShowEmojis(false); anim.setValue(0);
                                                                                                                                                                                              Animated.timing(anim, { toValue: 1, duration: 850, useNativeDriver: true }).start(() => setFlyEmoji(''));
                                                                                                                                                                                                  sendDM(e, true);
                                                                                                                                                                                                    };

                                                                                                                                                                                                      const toggleLike = () => {
                                                                                                                                                                                                          if (!active || !uid) return;
                                                                                                                                                                                                              const liked = (active.likes || []).includes(uid);
                                                                                                                                                                                                                  updateDoc(doc(db, 'stories', active.id), { likes: liked ? arrayRemove(uid) : arrayUnion(uid) }).catch(() => {});
                                                                                                                                                                                                                    };

                                                                                                                                                                                                                      const addComment = () => {
                                                                                                                                                                                                                          if (!active || !uid || !cText.trim()) return;
                                                                                                                                                                                                                              const item = { id: String(Date.now()), username: me?.username || 'user', text: cText.trim() };
                                                                                                                                                                                                                                  setCText('');
                                                                                                                                                                                                                                      updateDoc(doc(db, 'stories', active.id), { comments: arrayUnion(item) }).catch(() => {});
                                                                                                                                                                                                                                        };

                                                                                                                                                                                                                                          const liked = active && uid ? (active.likes || []).includes(uid) : false;
                                                                                                                                                                                                                                            const flyX = anim.interpolate({ inputRange: [0, 1], outputRange: [0, -140] });
                                                                                                                                                                                                                                              const flyY = anim.interpolate({ inputRange: [0, 1], outputRange: [0, -340] });
                                                                                                                                                                                                                                                const flyOp = anim.interpolate({ inputRange: [0, 0.7, 1], outputRange: [1, 0.9, 0] });

                                                                                                                                                                                                                                                  return (
                                                                                                                                                                                                                                                      <Modal visible={!!active} animationType="fade">
                                                                                                                                                                                                                                                            <View style={styles.modal}>
                                                                                                                                                                                                                                                                    {active?.mediaType === 'video' ? <StoryVideo uri={active.mediaUrl} /> : <Image source={{ uri: active?.mediaUrl }} style={styles.media} />}
                                                                                                                                                                                                                                                                            <View style={styles.progBg}><View style={[styles.progFill, { width: `${progress}%` }]} /></View>

                                                                                                                                                                                                                                                                                    <View style={styles.top}>
                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => active?.uid === uid && setShowViewers(!showViewers)}>
                                                                                                                                                                                                                                                                                                          <Text style={{ color: '#fff', fontWeight: '700' }}>@{active?.username} • {active?.viewers?.length || 0} views {active?.uid === uid ? '▾' : ''}</Text>
                                                                                                                                                                                                                                                                                                                    </TouchableOpacity>
                                                                                                                                                                                                                                                                                                                              <TouchableOpacity hitSlop={12} onPress={() => setActiveIdx(null)}><Ionicons name="close" size={28} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                      </View>

                                                                                                                                                                                                                                                                                                                                              {showViewers && (
                                                                                                                                                                                                                                                                                                                                                        <View style={styles.box}>
                                                                                                                                                                                                                                                                                                                                                                    <Text style={{ color: '#fff', fontWeight: '700', marginBottom: 6 }}>Viewers</Text>
                                                                                                                                                                                                                                                                                                                                                                                {(active?.viewerNames || []).map((n: string, i: number) => <Text key={i} style={{ color: '#E5E7EB', paddingVertical: 2 }}>@{n}</Text>)}
                                                                                                                                                                                                                                                                                                                                                                                          </View>
                                                                                                                                                                                                                                                                                                                                                                                                  )}

                                                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.navOverlay}>
                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity style={{ flex: 1 }} onPress={() => activeIdx! > 0 && setActiveIdx(activeIdx! - 1)} />
                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity style={{ flex: 1 }} onPress={() => activeIdx! < stories.length - 1 ? setActiveIdx(activeIdx! + 1) : setActiveIdx(null)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                              {!!flyEmoji && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                        <Animated.Text style={[styles.fly, { opacity: flyOp, transform: [{ translateX: flyX }, { translateY: flyY }] }]}>{flyEmoji}</Animated.Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {showEmojis && (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.emojiGrid}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {EMOJIS.map((e) => <TouchableOpacity key={e} onPress={() => triggerReaction(e)}><Text style={{ fontSize: 34 }}>{e}</Text></TouchableOpacity>)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                )}

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={styles.bottom}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TextInput
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={styles.input} placeholder="Send message" placeholderTextColor="#ccc"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          value={reply} onChangeText={setReply} onFocus={() => setShowEmojis(true)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      onSubmitEditing={() => { sendDM(reply, false); setReply(''); setShowEmojis(false); }}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={toggleLike}><Ionicons name={liked ? 'heart' : 'heart-outline'} size={25} color={liked ? '#EF4444' : '#fff'} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <TouchableOpacity onPress={() => setShowComments(true)}><Ionicons name="chatbubble-outline" size={23} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <TouchableOpacity onPress={() => setShareItem(active)}><Ionicons name="paper-plane-outline" size={23} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </View>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Modal visible={showComments} animationType="slide" transparent>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <View style={styles.cBg}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <View style={styles.cCard}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <View style={styles.cHead}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Text style={{ color: '#fff', fontWeight: '700', fontSize: 16 }}>Story Comments</Text>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <TouchableOpacity onPress={() => setShowComments(false)}><Ionicons name="close" size={24} color="#fff" /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <FlatList
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              style={{ flex: 1 }} data={active?.comments || []} keyExtractor={(i: any) => i.id}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ListEmptyComponent={<Text style={{ color: '#9CA3AF', textAlign: 'center', marginTop: 24 }}>No comments yet.</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              renderItem={({ item }) => <Text style={{ color: '#fff', paddingVertical: 6 }}><Text style={{ fontWeight: '700' }}>@{item.username} </Text>{item.text}</Text>}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <View style={styles.cRow}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TextInput style={styles.cInp} placeholder="Add comment..." placeholderTextColor="#9CA3AF" value={cText} onChangeText={setCText} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <TouchableOpacity onPress={addComment}><Ionicons name="send" size={22} color={BRAND} /></TouchableOpacity>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <ShareModal post={shareItem} onClose={() => setShareItem(null)} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </View>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </Modal>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const styles = StyleSheet.create({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            modal: { flex: 1, backgroundColor: '#000', justifyContent: 'center' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              media: { width: '100%', height: '100%', resizeMode: 'contain' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                progBg: { position: 'absolute', top: 38, left: 12, right: 12, height: 3, backgroundColor: 'rgba(255,255,255,0.3)', borderRadius: 2, zIndex: 12 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  progFill: { height: 3, backgroundColor: '#fff', borderRadius: 2 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    top: { position: 'absolute', top: 50, left: 16, right: 16, flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', zIndex: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      box: { position: 'absolute', top: 90, left: 16, right: 16, backgroundColor: 'rgba(0,0,0,0.8)', padding: 14, borderRadius: 12, zIndex: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        navOverlay: { position: 'absolute', top: 90, bottom: 90, left: 0, right: 0, flexDirection: 'row' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          fly: { position: 'absolute', alignSelf: 'center', top: '48%', fontSize: 54, zIndex: 30 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            emojiGrid: { position: 'absolute', bottom: 84, alignSelf: 'center', flexDirection: 'row', flexWrap: 'wrap', width: 240, justifyContent: 'space-around', gap: 14, backgroundColor: 'rgba(0,0,0,0.65)', padding: 16, borderRadius: 20, zIndex: 25 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              bottom: { position: 'absolute', bottom: 24, left: 14, right: 14, flexDirection: 'row', alignItems: 'center', gap: 12, zIndex: 20 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                input: { flex: 1, borderWidth: 1, borderColor: '#666', borderRadius: 24, paddingHorizontal: 16, paddingVertical: 9, color: '#fff' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  cBg: { flex: 1, backgroundColor: 'rgba(0,0,0,0.55)', justifyContent: 'flex-end' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    cCard: { height: '55%', backgroundColor: '#18181B', borderTopLeftRadius: 20, borderTopRightRadius: 20, padding: 16 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cHead: { flexDirection: 'row', justifyContent: 'space-between', paddingBottom: 10, borderBottomWidth: 1, borderBottomColor: '#27272A' },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cRow: { flexDirection: 'row', alignItems: 'center', gap: 10, paddingTop: 10 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          cInp: { flex: 1, backgroundColor: '#27272A', color: '#fff', borderRadius: 20, paddingHorizontal: 14, paddingVertical: 8 },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          